use super::*;
use semio_framework_value::{list::persistent::{PersistentList,PERSISTENT_PAGE_FANOUT},retained_clone::{RetainedCloneSource,RetainedCloneCursor},retirement::{RetireOwned,shared::sealed::{SealedShared,SharedIssuer}}};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[derive(semio_framework_value::RetireOwned,semio_framework_value::CanonicalJsonTree)]
#[canonical_json(owner=crate)]
struct Row {label:String,rank:i64}
impl Clone for Row{fn clone(&self)->Self{panic!("original canonical tree must borrow its rows")}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes.max(4096),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn rows(count:usize,prefix:&str,stride:i64)->PersistentList<Row>{
 if count==0{return Default::default();}let mut level=Vec::new();for start in(0..count).step_by(PERSISTENT_PAGE_FANOUT){let length=(count-start).min(PERSISTENT_PAGE_FANOUT);let rows=std::array::from_fn(|slot|if slot<length{let rank=start+slot;Some(SealedShared::admit(Row{label:format!("{prefix}{rank}"),rank:rank as i64*stride},SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<Row>::birth_bytes(),maximum_depth:1,..Default::default()}).unwrap_or_else(|_|panic!("original canonical row birth")).0)}else{None});level.push(PersistentList::admit_leaf(rows,length,grant(PersistentList::<Row>::page_birth_demand())).unwrap_or_else(|_|panic!("original canonical leaf birth")).0);}while level.len()>1{let mut input=level.into_iter();let mut next=Vec::new();loop{let children=std::array::from_fn(|_|input.next());if children[0].is_none(){break;}next.push(PersistentList::admit_branch(children,grant(PersistentList::<Row>::page_birth_demand())).unwrap_or_else(|_|panic!("original canonical branch birth")).0);}level=next;}level.pop().unwrap()
}
/// 📋️ Real persistent and sealed native trees borrow original rows and encode exact canonical arrays through cancellation.
#[test]
fn original_persistent_canonical_tree_preserves_native_rows_and_exact_wire(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let prefix=fixture["prefix"].as_str().unwrap();let stride=fixture["stride"].as_i64().unwrap();
 for count in fixture["lengths"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;let oracle=serde_json::to_vec(&(0..count).map(|i|serde_json::json!({"label":format!("{prefix}{i}"),"rank":i as i64*stride})).collect::<Vec<_>>()).unwrap();for cut in std::iter::once(None).chain(fixture["cuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize))){
 let(original,mut total)=observe(||rows(count,prefix,stride));let(_,heap)=observe(||{assert!(matches!(original.canonical_tree_node().unwrap(),Node::Array(n)if n==count));for i in 0..count{assert_eq!(original.canonical_tree_child(i).unwrap()as*const dyn ArtifactCanonicalJsonTree as*const(),original.get(i).unwrap()as*const Row as*const());}assert!(original.canonical_tree_child(count).is_err());});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let d=RetainedCloneSource::<PersistentList<Row>>::owned_constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<PersistentList<Row>>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});let((mut source,p),heap)=observe(||RetainedCloneSource::admit_owned(original,(),g).unwrap_or_else(|_|panic!("original canonical source")));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));total.requested_bytes+=heap.requested_bytes;total.released_bytes+=heap.released_bytes;
 let(projection,heap)=observe(||source.project_owned(0,|root|root as&dyn ArtifactCanonicalJsonTree,grant(RetirementDemand{copy_bytes:source.borrow().binding_copy_bytes(),depth:1,..Default::default()})).unwrap().0);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let((mut cursor,_),heap)=observe(||ArtifactCanonicalJsonTreeCursor::admit(projection,grant(ArtifactCanonicalJsonTreeCursor::constructor_demand())).unwrap_or_else(|_|panic!("original canonical cursor")));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut output=Vec::new();let mut turns=0;
 while !cursor.terminal_is_empty(){if cut==Some(turns){cursor.begin_close();}let(d,heap)=observe(||cursor.next_demand().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let g=grant(d);let mut bytes=[0;512];let(step,heap)=observe(||cursor.advance(&mut bytes,g).unwrap());let p=step.ownership.progress();assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));total.requested_bytes+=heap.requested_bytes;total.released_bytes+=heap.released_bytes;output.extend_from_slice(&bytes[..step.written_bytes]);turns+=1;}
 if cut.is_none(){assert!(cursor.is_complete());assert_eq!(output,oracle);}else{assert_eq!(output,oracle[..output.len()]);}let(_,heap)=observe(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 while !source.terminal_is_empty(){let d=source.next_close_demands(4096).unwrap();let g=grant(d);let(step,heap)=observe(||source.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));total.requested_bytes+=heap.requested_bytes;total.released_bytes+=heap.released_bytes;}let(_,heap)=observe(||drop(source));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(total.requested_bytes,total.released_bytes);eprintln!("[DEBUG] original persistent canonical rows={count} cut={cut:?} turns={turns} physicalBirth={} physicalRelease={} nativePointers=true clone=0",total.requested_bytes,total.released_bytes);
 }}
 let(text,mut total)=observe(||SealedShared::admit(String::from(prefix),SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<String>::birth_bytes(),maximum_depth:1,..Default::default()}).unwrap_or_else(|_|panic!("original canonical text")).0);let(_,heap)=observe(||{assert!(matches!(text.canonical_tree_node().unwrap(),Node::String(value)if value.as_ptr()==text.get().as_ptr()));assert!(text.canonical_tree_child(0).is_err());assert!(text.canonical_tree_key(0).is_err());});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(text).unwrap_or_else(|_|panic!("original text close"));while !owner.terminal_is_empty(){let g=grant(owner.next_demand(4096).unwrap());let(step,heap)=observe(||owner.step(g).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));total.requested_bytes+=heap.requested_bytes;total.released_bytes+=heap.released_bytes;}assert_eq!(total.requested_bytes,total.released_bytes);
}
